//! The canon and its versification structure (B078): book order, chapters per book and
//! verses per chapter in the Paratext `eng` scheme (English, KJV-style, Psalm titles as
//! verse 0) and the `org` scheme (the original numbering: Hebrew BHS/WLC in the Old
//! Testament), with the `eng` ↔ `org` rows between them. Structure only, no text.
//!
//! The table ([`data`], generated by `tools/gen_canon.py`) comes from S51, the Copenhagen
//! Alliance versification mappings derived from the Paratext `.vrs` files (CC BY-SA 4.0;
//! [`SOURCE`] names the commit). It covers the 66 books of [`BookId`]; deuterocanonical
//! books are in the same source and join when `BookId` gains them (the generator's book list
//! and the arrays grow together, and [`BookOrder`] gains the orders that include them).
//!
//! Mapping follows the `.vrs` rule the table was written under: a verse that no row covers
//! has the same number in both schemes, provided the target scheme has that verse. This is
//! a complete table, so unlike a [`crate::versification::VerseMap`] of fixture rows an
//! unlisted verse is not unknown; a verse the target does not have is still
//! [`MappingStatus::Unmapped`]. Several `eng` verses that land on one `org` verse (English
//! Psalm 13:5–6 in Hebrew 13:6) are each [`MappingStatus::Partial`] going to `org`, and the
//! `org` verse maps back exactly to all of them.

use serde::{Deserialize, Serialize};

use crate::reference::{BookId, Reference};
use crate::versification::{MappingResult, MappingStatus, SchemeId};

// Generated arrays, one book per line.
#[rustfmt::skip]
mod data;

/// Where the table comes from: S51 at a pinned commit.
pub const SOURCE: &str = concat!(
    "S51 Copenhagen Alliance versification mappings (Paratext eng.vrs and org.vrs as JSON), ",
    "https://github.com/Copenhagen-Alliance/versification-specification, CC BY-SA 4.0"
);

/// The S51 commit the table was generated from.
#[must_use]
pub fn source_commit() -> &'static str {
    data::SOURCE_COMMIT
}

/// The schemes the table knows: `eng` and `org`.
pub const SCHEMES: [&str; 2] = ["eng", "org"];

/// A book order for an edition's reading stream.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum BookOrder {
    /// Genesis → Malachi, Matthew → Revelation: [`BookId`] order.
    #[default]
    Protestant,
    /// The Hebrew Bible in the order of BHS (Torah, Prophets, Writings ending with
    /// Chronicles). Offered for a WLC pack that wants it; no edition uses it yet.
    TanakhBhs,
}

const TANAKH_BHS: [BookId; 39] = {
    use BookId::*;
    [
        Gen, Exod, Lev, Num, Deut, Josh, Judg, Sam1, Sam2, Kgs1, Kgs2, Isa, Jer, Ezek, Hos, Joel,
        Amos, Obad, Jonah, Mic, Nah, Hab, Zeph, Hag, Zech, Mal, Ps, Job, Prov, Ruth, Song, Eccl,
        Lam, Esth, Dan, Ezra, Neh, Chr1, Chr2,
    ]
};

impl BookOrder {
    /// The books of the order that are in `books`, in the order's sequence; books the order
    /// does not place keep their [`BookId`] order after it.
    #[must_use]
    pub fn arrange(self, books: &[BookId]) -> Vec<BookId> {
        match self {
            BookOrder::Protestant => {
                let mut out = books.to_vec();
                out.sort();
                out.dedup();
                out
            }
            BookOrder::TanakhBhs => {
                let mut out: Vec<BookId> = TANAKH_BHS
                    .iter()
                    .copied()
                    .filter(|b| books.contains(b))
                    .collect();
                let mut rest: Vec<BookId> = books
                    .iter()
                    .copied()
                    .filter(|b| !TANAKH_BHS.contains(b))
                    .collect();
                rest.sort();
                rest.dedup();
                out.extend(rest);
                out
            }
        }
    }
}

/// The Old Testament: Genesis to Malachi.
#[must_use]
pub fn old_testament() -> Vec<BookId> {
    BookId::all()
        .into_iter()
        .filter(|b| *b <= BookId::Mal)
        .collect()
}

/// The New Testament: Matthew to Revelation.
#[must_use]
pub fn new_testament() -> Vec<BookId> {
    BookId::all()
        .into_iter()
        .filter(|b| *b > BookId::Mal)
        .collect()
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Scheme {
    Eng,
    Org,
}

fn scheme(id: &SchemeId) -> Option<Scheme> {
    match id.as_str() {
        "eng" => Some(Scheme::Eng),
        "org" => Some(Scheme::Org),
        _ => None,
    }
}

fn table(scheme: Scheme) -> &'static [&'static [u8]; 66] {
    match scheme {
        Scheme::Eng => &data::ENG,
        Scheme::Org => &data::ORG,
    }
}

/// Whether the table knows this scheme.
#[must_use]
pub fn knows(id: &SchemeId) -> bool {
    scheme(id).is_some()
}

/// Chapters of `book` in the scheme (Joel has 3 in `eng`, 4 in `org`); `None` for a scheme
/// the table does not know.
#[must_use]
pub fn chapter_count(id: &SchemeId, book: BookId) -> Option<u32> {
    let scheme = scheme(id)?;
    Some(table(scheme)[book.canonical_index() as usize].len() as u32)
}

/// The last verse of a chapter; `None` for an unknown scheme or a chapter the book does not
/// have.
#[must_use]
pub fn last_verse(id: &SchemeId, book: BookId, chapter: u32) -> Option<u32> {
    let scheme = scheme(id)?;
    let chapters = table(scheme)[book.canonical_index() as usize];
    let index = usize::try_from(chapter.checked_sub(1)?).ok()?;
    chapters.get(index).map(|v| u32::from(*v))
}

/// The first verse of a chapter: 0 for a Psalm whose title `eng` numbers as verse 0, else 1;
/// `None` when the chapter does not exist.
#[must_use]
pub fn first_verse(id: &SchemeId, book: BookId, chapter: u32) -> Option<u32> {
    last_verse(id, book, chapter)?;
    let titled = scheme(id) == Some(Scheme::Eng)
        && data::ENG_TO_ORG.iter().any(|r| {
            u32::from(r.0) == book.canonical_index() && u32::from(r.1) == chapter && r.2 == 0
        });
    Some(u32::from(!titled))
}

/// Whether the scheme has this verse (a chapter-only reference: whether it has the chapter).
#[must_use]
pub fn contains(id: &SchemeId, reference: &Reference) -> bool {
    let Some(last) = last_verse(id, reference.book, reference.chapter) else {
        return false;
    };
    match reference.verse {
        None => true,
        Some(verse) => {
            let first = first_verse(id, reference.book, reference.chapter).unwrap_or(1);
            (first..=last).contains(&verse)
        }
    }
}

/// The row covering an `eng` verse: its `org` chapter and verse.
fn eng_row(book: u32, chapter: u32, verse: u32) -> Option<(u32, u32)> {
    data::ENG_TO_ORG.iter().find_map(|r| {
        (u32::from(r.0) == book
            && u32::from(r.1) == chapter
            && (u32::from(r.2)..=u32::from(r.3)).contains(&verse))
        .then(|| (u32::from(r.4), u32::from(r.5) + verse - u32::from(r.2)))
    })
}

/// `eng` verses (rows and the unlisted same-number verse) that land on an `org` verse.
fn eng_sources(book: BookId, chapter: u32, verse: u32) -> Vec<Reference> {
    let index = book.canonical_index();
    let mut out: Vec<Reference> = data::ENG_TO_ORG
        .iter()
        .filter(|r| u32::from(r.0) == index && u32::from(r.4) == chapter)
        .filter_map(|r| {
            let offset = verse.checked_sub(u32::from(r.5))?;
            (offset <= u32::from(r.3 - r.2))
                .then(|| Reference::verse(book, u32::from(r.1), u32::from(r.2) + offset))
        })
        .collect();
    let eng = SchemeId::new("eng");
    let same = Reference::verse(book, chapter, verse);
    if eng_row(index, chapter, verse).is_none() && contains(&eng, &same) {
        out.push(same);
    }
    out.sort();
    out
}

/// The `org` verse an `eng` verse is numbered as, if `org` has it.
fn eng_to_org(book: BookId, chapter: u32, verse: u32) -> Option<Reference> {
    let (c, v) = eng_row(book.canonical_index(), chapter, verse).unwrap_or((chapter, verse));
    let target = Reference::verse(book, c, v);
    contains(&SchemeId::org(), &target).then_some(target)
}

/// Maps one verse between `eng` and `org` (either direction, or within one scheme) by the
/// table's rules; a sub-verse grain is dropped. A chapter-only reference, a verse the source
/// scheme does not have, a verse the target does not have and a scheme the table does not
/// know are [`MappingStatus::Unmapped`].
#[must_use]
pub fn map(reference: &Reference, from: &SchemeId, to: &SchemeId) -> MappingResult {
    let path = if from == to {
        vec![from.clone()]
    } else {
        vec![from.clone(), to.clone()]
    };
    let unmapped = MappingResult {
        status: MappingStatus::Unmapped,
        targets: Vec::new(),
        path: path.clone(),
    };
    let (Some(source), Some(target), Some(verse)) = (scheme(from), scheme(to), reference.verse)
    else {
        return unmapped;
    };
    let plain = Reference::verse(reference.book, reference.chapter, verse);
    if !contains(from, &plain) {
        return unmapped;
    }
    let (status, targets) = match (source, target) {
        (Scheme::Eng, Scheme::Org) => match eng_to_org(plain.book, plain.chapter, verse) {
            None => return unmapped,
            Some(t) => {
                let shared = eng_sources(t.book, t.chapter, t.verse.unwrap_or(0)).len() > 1;
                let status = if shared {
                    MappingStatus::Partial
                } else {
                    MappingStatus::Exact
                };
                (status, vec![t])
            }
        },
        (Scheme::Org, Scheme::Eng) => {
            let sources = eng_sources(plain.book, plain.chapter, verse);
            if sources.is_empty() {
                return unmapped;
            }
            (MappingStatus::Exact, sources)
        }
        _ => (MappingStatus::Exact, vec![plain]),
    };
    MappingResult {
        status,
        targets,
        path,
    }
}

/// The verse a segment id starts at: `John.3.16` → John 3:16, a bridge `Num.26.3-4` → Numbers
/// 26:3, a split verse `Num.26.5a` → Numbers 26:5, a Psalm title `Ps.3.0` → Psalm 3:0.
/// `None` for an id that is not `Book.C.V` with an optional suffix (a note paragraph, a
/// commentary locator).
#[must_use]
pub fn segment_reference(segment_id: &str) -> Option<Reference> {
    let mut parts = segment_id.splitn(3, '.');
    let book = BookId::from_osis(parts.next()?)?;
    let chapter: u32 = parts.next()?.parse().ok().filter(|c| *c > 0)?;
    let rest = parts.next()?;
    let digits = rest.len() - rest.trim_start_matches(|c: char| c.is_ascii_digit()).len();
    let verse: u32 = rest[..digits].parse().ok()?;
    let suffix = &rest[digits..];
    let valid_suffix = suffix.is_empty()
        || suffix.chars().all(|c| c.is_ascii_lowercase())
        || suffix
            .strip_prefix('-')
            .is_some_and(|end| !end.is_empty() && end.chars().all(|c| c.is_ascii_digit()));
    valid_suffix.then(|| Reference::verse(book, chapter, verse))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn eng() -> SchemeId {
        SchemeId::new("eng")
    }

    fn v(book: BookId, c: u32, v: u32) -> Reference {
        Reference::verse(book, c, v)
    }

    #[test]
    fn the_table_has_every_book_and_the_known_totals() {
        let total = |id: &SchemeId| -> u32 {
            BookId::all()
                .into_iter()
                .map(|b| {
                    (1..=chapter_count(id, b).unwrap())
                        .map(|c| last_verse(id, b, c).unwrap())
                        .sum::<u32>()
                })
                .sum()
        };
        // 31,102 verses in the KJV plus Acts 19:41 and 2 Cor 13:14 as eng counts them.
        assert_eq!(total(&eng()), 31104);
        assert_eq!(chapter_count(&eng(), BookId::Ps), Some(150));
        assert_eq!(last_verse(&eng(), BookId::Ps, 119), Some(176));
        assert_eq!(chapter_count(&eng(), BookId::Joel), Some(3));
        assert_eq!(chapter_count(&SchemeId::org(), BookId::Joel), Some(4));
        assert_eq!(chapter_count(&eng(), BookId::Mal), Some(4));
        assert_eq!(chapter_count(&SchemeId::org(), BookId::Mal), Some(3));
        assert_eq!(last_verse(&eng(), BookId::Rev, 22), Some(21));
        assert_eq!(last_verse(&eng(), BookId::Rev, 23), None);
        assert_eq!(chapter_count(&SchemeId::new("lxx"), BookId::Gen), None);
    }

    #[test]
    fn psalm_titles_are_verse_zero_in_eng_only() {
        assert_eq!(first_verse(&eng(), BookId::Ps, 3), Some(0));
        assert_eq!(first_verse(&eng(), BookId::Ps, 1), Some(1));
        assert_eq!(first_verse(&SchemeId::org(), BookId::Ps, 3), Some(1));
        assert!(contains(&eng(), &v(BookId::Ps, 3, 0)));
        assert!(!contains(&eng(), &v(BookId::Ps, 1, 0)));
    }

    #[test]
    fn joel_malachi_and_psalms_map_both_ways() {
        let org = SchemeId::org();
        let one = |r: Reference, from: &SchemeId, to: &SchemeId| {
            let m = map(&r, from, to);
            (m.status, m.targets)
        };
        use MappingStatus::*;
        assert_eq!(
            one(v(BookId::Joel, 2, 28), &eng(), &org),
            (Exact, vec![v(BookId::Joel, 3, 1)])
        );
        assert_eq!(
            one(v(BookId::Joel, 4, 1), &org, &eng()),
            (Exact, vec![v(BookId::Joel, 3, 1)])
        );
        assert_eq!(
            one(v(BookId::Mal, 4, 6), &eng(), &org),
            (Exact, vec![v(BookId::Mal, 3, 24)])
        );
        assert_eq!(
            one(v(BookId::Joel, 4, 22), &org, &eng()),
            (Unmapped, vec![])
        );
        assert_eq!(
            one(v(BookId::Ps, 9, 0), &eng(), &org),
            (Exact, vec![v(BookId::Ps, 9, 1)])
        );
        assert_eq!(
            one(v(BookId::Ps, 13, 5), &eng(), &org),
            (Partial, vec![v(BookId::Ps, 13, 6)])
        );
        assert_eq!(
            one(v(BookId::Ps, 13, 6), &org, &eng()),
            (Exact, vec![v(BookId::Ps, 13, 5), v(BookId::Ps, 13, 6)])
        );
        assert_eq!(
            one(v(BookId::John, 3, 16), &eng(), &org),
            (Exact, vec![v(BookId::John, 3, 16)])
        );
        assert_eq!(one(v(BookId::Gen, 1, 99), &eng(), &org), (Unmapped, vec![]));
        assert_eq!(
            map(&Reference::chapter(BookId::Joel, 3), &eng(), &org).status,
            Unmapped
        );
    }

    #[test]
    fn every_eng_verse_round_trips_through_org() {
        let org = SchemeId::org();
        let mut unmapped = Vec::new();
        for book in BookId::all() {
            for c in 1..=chapter_count(&eng(), book).unwrap() {
                let first = first_verse(&eng(), book, c).unwrap();
                for verse in first..=last_verse(&eng(), book, c).unwrap() {
                    let r = v(book, c, verse);
                    let there = map(&r, &eng(), &org);
                    if there.status == MappingStatus::Unmapped {
                        unmapped.push(r.to_osis());
                        continue;
                    }
                    let back = map(&there.targets[0], &org, &eng());
                    assert!(back.targets.contains(&r), "{r} -> {:?}", there.targets);
                }
            }
        }
        // English verses the original numbering folds into a neighbour.
        assert_eq!(unmapped, ["Acts.19.41", "2Cor.13.14"]);
    }

    #[test]
    fn segment_ids_name_their_first_verse() {
        assert_eq!(segment_reference("John.3.16"), Some(v(BookId::John, 3, 16)));
        assert_eq!(segment_reference("Num.26.3-4"), Some(v(BookId::Num, 26, 3)));
        assert_eq!(segment_reference("Num.26.5a"), Some(v(BookId::Num, 26, 5)));
        assert_eq!(segment_reference("Ps.3.0"), Some(v(BookId::Ps, 3, 0)));
        assert_eq!(segment_reference("John.3"), None);
        assert_eq!(segment_reference("fixture:note:1#p1"), None);
        assert_eq!(segment_reference("John.3.16.2"), None);
        assert_eq!(segment_reference("John.0.1"), None);
    }

    #[test]
    fn orders_arrange_the_books_an_edition_has() {
        let ot = old_testament();
        assert_eq!(ot.len(), 39);
        assert_eq!(new_testament().len(), 27);
        assert_eq!(BookOrder::Protestant.arrange(&ot), ot);
        let tanakh = BookOrder::TanakhBhs.arrange(&ot);
        assert_eq!(tanakh.len(), 39);
        assert_eq!(tanakh[25], BookId::Mal);
        assert_eq!(tanakh[26], BookId::Ps);
        assert_eq!(tanakh[38], BookId::Chr2);
    }
}
